def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = 0
    for me, opp in history:
        if opp == 'C':
            opp_c += 1
    opp_rate = opp_c / float(n)

    last_me, last_opp = history[-1]
    prev_my = history[-2][0] if n >= 2 else 'C'

    oppD = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            oppD += 1
        else:
            break

    myD = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            myD += 1
        else:
            break

    oppC = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            oppC += 1
        else:
            break

    start10 = n - 10
    if start10 < 0:
        start10 = 0
    start5 = n - 5
    if start5 < 0:
        start5 = 0

    recent10_c = 0
    for i in range(start10, n):
        if history[i][1] == 'C':
            recent10_c += 1

    recent5_c = 0
    for i in range(start5, n):
        if history[i][1] == 'C':
            recent5_c += 1

    resp_start = n - 10
    if resp_start < 1:
        resp_start = 1
    recent_resp_c = 0
    recent_resp_d = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if i >= resp_start:
                if history[i][1] == 'D':
                    recent_resp_d += 1
                else:
                    recent_resp_c += 1

    hard_defector = False
    if n >= 12 and opp_rate < 0.25:
        hard_defector = True
    if recent10_c <= 4 and oppD >= 5:
        hard_defector = True
    if recent5_c == 0 and oppD >= 6:
        hard_defector = True

    if hard_defector:
        if last_opp == 'C':
            if recent5_c >= 2 or rng.random() < 0.35:
                return 'C'
            return 'D'
        return 'D'

    if last_opp == 'D':
        if n >= 2 and prev_my == 'D':
            if recent10_c <= 4 and oppD >= 4:
                return 'D'
            return 'C'
        if myD >= 5 and (recent10_c >= 4 or opp_rate > 0.55) and rng.random() < 0.5:
            return 'C'
        return 'D'

    if recent_resp_d == 0:
        if (
            n >= 2
            and recent_resp_c >= 1
            and last_me == 'C'
            and last_opp == 'C'
            and history[-2][0] == 'D'
        ):
            return 'D'
        if recent_resp_c >= 2 and (opp_rate >= 0.75 or recent10_c >= 8):
            return 'D'
        if recent_resp_c >= 1 and opp_rate >= 0.97 and oppC >= 20:
            return 'D'

    if (
        opp_rate >= 0.85
        and recent10_c >= 8
        and oppC >= 15
        and rng.random() < 0.025
    ):
        return 'D'

    return 'C'
